import{_ as s,l as i,o as e,c as n,v as t,p as l,x as r,d as p,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"计算栈到此为止","description":"","frontmatter":{"title":"计算栈到此为止","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/to-systems-boundary.md","filePath":"cs/to-systems-boundary.md","lastUpdated":1789023840000}'),A={name:"cs/to-systems-boundary.md"};function c(h,a,u,m,_,B){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="计算栈到此为止" tabindex="-1">计算栈到此为止 <a class="header-anchor" href="#计算栈到此为止" aria-label="Permalink to &quot;计算栈到此为止&quot;">​</a></h1><div class="epigraph"><p>从比特到隔离与会话，系统栈在此封口；词表上的训练、盘口上的价格，是另外两栏的第一课，不在这里续写。</p><footer>—— 本栏课程序列的边界声明</footer></div><p><a href="/cs/injection-boundary">上一课</a>把不可信输入收到解释器边界。本课不补一种新协议，也不重做注入分类。缺口是：计算机栏从<a href="/cs/bit-as-distinction">比特作为区分</a>走到组成、体系结构、数据与算法、编译、操作系统、网络、数据库、安全，对象始终是可执行的系统栈。再往前写就会吞并别的栏，或把附录论文插进主干。本课只封口并移交。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>栈已经能表示数、跑指令、调度进程、传报文、提交事务、谈 CIA。若在此续写注意力、残差或限价簿队列，就违反五栏互不吞并：大模型是 Transformer 与训练/推理；量化是金融微观结构与定价。金融与光刻是另两栏。缺口因此不是「计算机还有很多词条」，而是<strong>停在系统边界</strong>，把读者送到正确的第一课。</p><p><span class="marginnote">论文、教科书、EDVAC 报告是附录对照，不插入主干。下一篇起标「附录对照，不插入主干」，从 Turing 1936 起按文献读，不按课序进度读。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>主干在本课结束。大模型栏从<a href="/llm/token-as-discrete-unit">离散符号</a>再起：那里假定词表已在，不问页表与 WAL。量化从<a href="/quant/lob-structure">限价簿</a>起：价格与队列是市场对象，不是本栏的套接字缓冲。金融栏接到限价簿为止，不在本栏重写 LOB；光刻走成像与产线。本栏也不重写 Transformer。</p>',8)),(e(),l(E,null,{default:r(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CS%5B%22%E8%AE%A1%E7%AE%97%E6%9C%BA%E6%A0%8F%3A%20%E6%AF%94%E7%89%B9%E5%88%B0%E7%B3%BB%E7%BB%9F%E6%A0%88%22%5D%20--%3E%20STOP%5B%22%E6%9C%AC%E8%AF%BE%E5%B0%81%E5%8F%A3%22%5D%0A%20%20STOP%20--%3E%20LLM%5B%22%E5%A4%A7%E6%A8%A1%E5%9E%8B%3A%20%E7%A6%BB%E6%95%A3%E7%AC%A6%E5%8F%B7%22%5D%0A%20%20STOP%20--%3E%20Q%5B%22%E9%87%8F%E5%8C%96%3A%20%E9%99%90%E4%BB%B7%E7%B0%BF%22%5D%0A%20%20STOP%20--%3E%20APP%5B%22%E9%99%84%E5%BD%95%3A%20%E6%96%87%E7%8C%AE%E5%AF%B9%E7%85%A7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>封口的机制是课序约定，不是一条新定理。后课（附录）只对照原文如何第一次写出本栏已经用过的观念：可计算、存储程序、通信、互斥、关系、公钥方向。读附录不能替代从比特读到本课。安全课最后几课已经假定 OS 隔离与 TLS 入口；它们不延伸到对抗样本或市场操纵。</p><p>附录文献按时间与主题对照主干已经用过的观念，不把课序再往前推一格。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不总结每一张知识树叶子。不把「全栈工程师清单」写成小结。也不在这里开始训练循环或 CAPM。若还缺系统课，应插在本课之前的主干里，而不是写在附录当论文读。</p><p>安全课的机制停在协议、隔离与可用；对抗样本、市场操纵、光刻工艺不是本栏对象。后课默认：主干已结束。附录第一篇对照 Turing 1936，链接回本课，并声明不插入主干。</p><p>本课没有新对象。读完 DoS，CIA 三轴都有机制名字，系统栈闭合。附录从下一篇起按文献对照，不再推进课序。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>五栏互不吞并：本栏不写注意力，不写盘口队列。</p></li><li><p>附录从 Turing 1936 起对照文献，声明不插入主干。</p></li><li><p>计算机栏停在系统栈：组成到安全，不含 Transformer，不进入限价簿。</p></li><li><p>大模型从<a href="/llm/token-as-discrete-unit">离散符号</a>再起；量化从<a href="/quant/lob-structure">限价簿</a>起；金融与光刻是另两栏。</p></li><li><p>附录对照文献，不推进课序。</p></li><li><p>出处：本栏课程序列；五栏互不吞并的写作约定。</p></li></ul>',9))])}const b=s(A,[["render",c]]);export{T as __pageData,b as default};
